L4_org_hierarchy_rollup.invariants_dsl:
spec Manager {
    field ic_count: Integer {}
    field ic_avg_salary: Number {}
    field manager_salary: Number {}
    field team_budget: Number {
        value == this.manager_salary + (this.ic_count * this.ic_avg_salary);
    }
    invariant bounds {
        this.ic_count >= 2;
        this.ic_count <= 15;
    }
}

spec Director {
    field director_salary: Number {}
    field department_budget: Number {
        value == this.director_salary + this.mgr.team_budget;
    }
    field mgr: Manager {}
}

spec VicePresident {
    field vp_salary: Number {}
    field division_budget: Number {
        value == this.vp_salary + this.dir.department_budget;
    }
    field dir: Director {}
}

spec CorporateOrg {
    field total_corporate_budget: Number {
        value == this.ceo_salary + this.vp.division_budget;
    }
    field ceo_salary: Number {}
    field vp: VicePresident {}
    invariant ceo_pay {
        this.ceo_salary >= 300000.0;
        this.ceo_salary <= 2000000.0;
    }
}

L4_data_center_topology.invariants_dsl:
spec ServerBlade {
    field power_draw_watts: Number {}
    field cooling_btu: Number {
        value == this.power_draw_watts * 3.412;
    }
    invariant blade_limits {
        this.power_draw_watts >= 250.0;
        this.power_draw_watts <= 1500.0;
    }
}

spec ServerRack {
    field blade_a: ServerBlade {}
    field blade_b: ServerBlade {}
    field switch_overhead_watts: Number {}
    field total_rack_power: Number {
        value == this.blade_a.power_draw_watts + this.blade_b.power_draw_watts + this.switch_overhead_watts;
    }
    field total_rack_cooling: Number {
        value == this.blade_a.cooling_btu + this.blade_b.cooling_btu;
    }
}

spec DataCenterRow {
    field rack_1: ServerRack {}
    field rack_2: ServerRack {}
    field total_row_power_kw: Number {
        value == (this.rack_1.total_rack_power + this.rack_2.total_rack_power) / 1000.0;
    }
}

spec Facility {
    field facility_name: String {}
    field total_facility_power_kw: Number {
        value == this.row.total_row_power_kw * this.facility_pue;
    }
    field facility_pue: Number {}
    field row: DataCenterRow {}
    invariant facility_limits {
        this.facility_pue >= 1.1;
        this.facility_pue <= 2.5;
    }
}
